import { readFileSync } from "node:fs";
import postgres from "postgres";

const env = readFileSync("apps/web/.env", "utf8");
const direct = env.match(/^DIRECT_URL=(.+)$/m)?.[1];
const pooler = env.match(/^DATABASE_URL=(.+)$/m)?.[1];

for (const [label, url] of [["direct", direct], ["pooler", pooler]]) {
  if (!url) { console.log(label, "MISSING"); continue; }
  const sql = postgres(url, { max: 1, connect_timeout: 10 });
  try {
    const [row] = await sql`select current_database() as db, version()`; 
    const tables = await sql`select tablename from pg_tables where schemaname='public' order by 1`;
    console.log(label, "OK", row.db, "| tables:", tables.map((t) => t.tablename).join(","));
    const enums = await sql`select t.typname from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typtype='e' order by 1`;
    console.log(label, "enums:", enums.map((e) => e.typname).join(","));
    const vault = await sql`select exists (select 1 from information_schema.schemata where schema_name='vault') as has_vault`;
    console.log(label, "vault:", vault[0].has_vault);
  } catch (e) {
    console.log(label, "FAIL", e.message);
  } finally {
    await sql.end();
  }
}

