-- =====================================================================
-- Migration: New 17-table schema
-- Tables: workspaces, groups, workspace_members, user_profiles, threads,
-- workflows, plans, plan_steps, chat_messages, runs, run_activities,
-- approval_requests, invites, thread_shares, notifications,
-- workspace_api_keys, files
-- =====================================================================

-- ─────────────────────────────────────────────────────────────────────
-- ENUMS
-- ─────────────────────────────────────────────────────────────────────

CREATE TYPE "public"."role" AS ENUM ('owner', 'editor', 'viewer');
CREATE TYPE "public"."thread_role" AS ENUM ('editor', 'viewer');
CREATE TYPE "public"."plan_level" AS ENUM ('free', 'pro');
CREATE TYPE "public"."group_kind" AS ENUM ('custom', 'system');
CREATE TYPE "public"."invite_kind" AS ENUM ('workspace', 'thread');
CREATE TYPE "public"."invite_status" AS ENUM ('pending', 'accepted', 'revoked', 'expired');
CREATE TYPE "public"."workflow_status" AS ENUM (
  'waiting', 'planning', 'running', 'awaiting_approval',
  'idle', 'paused', 'failed', 'completed'
);
CREATE TYPE "public"."message_role" AS ENUM ('user', 'assistant', 'system', 'tool');
CREATE TYPE "public"."message_status" AS ENUM (
  'draft', 'queued', 'streaming', 'completed', 'failed', 'interrupted'
);
CREATE TYPE "public"."run_status" AS ENUM (
  'pending', 'running', 'sleeping', 'waiting', 'awaiting_approval',
  'completed', 'failed', 'cancelled'
);
CREATE TYPE "public"."run_trigger" AS ENUM (
  'message', 'schedule', 'resume', 'approval', 'rerun'
);
CREATE TYPE "public"."activity_status" AS ENUM ('pending', 'active', 'complete', 'failed');
CREATE TYPE "public"."activity_type" AS ENUM ('tool', 'thinking', 'task', 'subtask', 'system');
CREATE TYPE "public"."approval_status" AS ENUM ('pending', 'approved', 'denied');
CREATE TYPE "public"."api_provider" AS ENUM (
  'groq', 'anakin', 'mem0', 'image', 'speech', 'transcription', 'video'
);
CREATE TYPE "public"."plan_status" AS ENUM ('draft', 'proposed', 'accepted', 'declined');
CREATE TYPE "public"."plan_step_status" AS ENUM ('pending', 'active', 'completed', 'skipped');
CREATE TYPE "public"."notification_type" AS ENUM (
  'system', 'workflow', 'run', 'security', 'webhook'
);

-- ─────────────────────────────────────────────────────────────────────
-- TABLES
-- ─────────────────────────────────────────────────────────────────────

-- 1. workspaces
CREATE TABLE "public"."workspaces" (
  "id"          text PRIMARY KEY,
  "name"        text NOT NULL,
  "created_by"  uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  "is_default"  boolean NOT NULL DEFAULT false,
  "created_at"  timestamptz NOT NULL DEFAULT now(),
  "updated_at"  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "workspaces_created_by_name_idx" ON "public"."workspaces" ("created_by", "name");

-- 2. groups
CREATE TABLE "public"."groups" (
  "id"            text PRIMARY KEY,
  "workspace_id"  text NOT NULL REFERENCES "public"."workspaces"("id") ON DELETE CASCADE,
  "user_id"       uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  "name"          text NOT NULL,
  "kind"          "public"."group_kind" NOT NULL DEFAULT 'custom',
  "position"      integer NOT NULL DEFAULT 0,
  "created_at"    timestamptz NOT NULL DEFAULT now(),
  "updated_at"    timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "groups_workspace_name_idx" ON "public"."groups" ("workspace_id", "name");
CREATE INDEX "groups_workspace_position_idx" ON "public"."groups" ("workspace_id", "position");

-- 3. workspace_members
CREATE TABLE "public"."workspace_members" (
  "id"            text PRIMARY KEY,
  "workspace_id"  text NOT NULL REFERENCES "public"."workspaces"("id") ON DELETE CASCADE,
  "user_id"       uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  "role"          "public"."role" NOT NULL DEFAULT 'viewer',
  "created_at"    timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "workspace_members_workspace_user_idx" ON "public"."workspace_members" ("workspace_id", "user_id");

-- 4. user_profiles
CREATE TABLE "public"."user_profiles" (
  "id"                          text PRIMARY KEY,
  "user_id"                     uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
  "onboarded"                   boolean NOT NULL DEFAULT false,
  "pre_answers"                 jsonb,
  "plan"                        "public"."plan_level" NOT NULL DEFAULT 'free',
  "prefer_own_keys_in_shared"   boolean NOT NULL DEFAULT false,
  "created_at"                  timestamptz NOT NULL DEFAULT now(),
  "updated_at"                  timestamptz NOT NULL DEFAULT now()
);

-- 5. threads
CREATE TABLE "public"."threads" (
  "id"                  text PRIMARY KEY,
  "workspace_id"        text NOT NULL REFERENCES "public"."workspaces"("id") ON DELETE CASCADE,
  "group_id"            text REFERENCES "public"."groups"("id") ON DELETE SET NULL,
  "user_id"             uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  "title"               text NOT NULL DEFAULT '',
  "deleted_at"          timestamptz,
  "share_enabled"       boolean NOT NULL DEFAULT false,
  "bound_workflow_id"   text,
  "created_at"          timestamptz NOT NULL DEFAULT now(),
  "updated_at"          timestamptz NOT NULL DEFAULT now(),
  "last_message_at"     timestamptz
);
CREATE INDEX "threads_user_workspace_last_msg_idx" ON "public"."threads" ("user_id", "workspace_id", "last_message_at" DESC);
CREATE INDEX "threads_group_idx" ON "public"."threads" ("group_id");

-- 6. workflows
CREATE TABLE "public"."workflows" (
  "id"              text PRIMARY KEY,
  "thread_id"       text REFERENCES "public"."threads"("id") ON DELETE SET NULL,
  "workspace_id"    text NOT NULL REFERENCES "public"."workspaces"("id") ON DELETE CASCADE,
  "user_id"         uuid NOT NULL,
  "title"           text NOT NULL,
  "description"     text,
  "status"          "public"."workflow_status" NOT NULL DEFAULT 'waiting',
  "auto_approve"    boolean NOT NULL DEFAULT false,
  "schema_version"  integer NOT NULL DEFAULT 1,
  "created_at"      timestamptz NOT NULL DEFAULT now(),
  "updated_at"      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "workflows_user_status_idx" ON "public"."workflows" ("user_id", "status");
CREATE INDEX "workflows_thread_idx" ON "public"."workflows" ("thread_id");

-- 7. plans
CREATE TABLE "public"."plans" (
  "id"          text PRIMARY KEY,
  "workflow_id" text NOT NULL UNIQUE REFERENCES "public"."workflows"("id") ON DELETE CASCADE,
  "title"       text NOT NULL,
  "objective"   text,
  "summary"     text,
  "status"      "public"."plan_status" NOT NULL DEFAULT 'draft',
  "created_at"  timestamptz NOT NULL DEFAULT now(),
  "updated_at"  timestamptz NOT NULL DEFAULT now()
);

-- 8. plan_steps
CREATE TABLE "public"."plan_steps" (
  "id"          text PRIMARY KEY,
  "plan_id"     text NOT NULL REFERENCES "public"."plans"("id") ON DELETE CASCADE,
  "position"    integer NOT NULL,
  "title"       text NOT NULL,
  "description" text,
  "status"      "public"."plan_step_status" NOT NULL DEFAULT 'pending',
  "created_at"  timestamptz NOT NULL DEFAULT now(),
  "updated_at"  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "plan_steps_plan_position_idx" ON "public"."plan_steps" ("plan_id", "position");

-- 9. chat_messages
CREATE TABLE "public"."chat_messages" (
  "id"            text PRIMARY KEY,
  "thread_id"     text NOT NULL REFERENCES "public"."threads"("id") ON DELETE CASCADE,
  "user_id"       uuid NOT NULL,
  "role"          "public"."message_role" NOT NULL,
  "content"       jsonb NOT NULL,
  "run_id"        text,
  "status"        "public"."message_status" NOT NULL DEFAULT 'completed',
  "queue_order"   integer,
  "created_at"    timestamptz NOT NULL DEFAULT now(),
  "updated_at"    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "chat_messages_thread_created_idx" ON "public"."chat_messages" ("thread_id", "created_at" ASC);
CREATE INDEX "chat_messages_thread_status_idx" ON "public"."chat_messages" ("thread_id", "status");

-- 10. runs
CREATE TABLE "public"."runs" (
  "id"              text PRIMARY KEY,
  "thread_id"       text NOT NULL REFERENCES "public"."threads"("id") ON DELETE CASCADE,
  "workflow_id"     text,
  "user_id"         uuid NOT NULL,
  "trigger"         "public"."run_trigger" NOT NULL,
  "rerun_of"        text REFERENCES "public"."runs"("id") ON DELETE SET NULL,
  "status"          "public"."run_status" NOT NULL DEFAULT 'pending',
  "prompt_snapshot" jsonb,
  "cost_usd"        numeric(10,6),
  "token_count"     bigint,
  "finished_at"     timestamptz,
  "created_at"      timestamptz NOT NULL DEFAULT now(),
  "updated_at"      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "runs_thread_created_idx" ON "public"."runs" ("thread_id", "created_at" DESC);
CREATE INDEX "runs_workflow_status_idx" ON "public"."runs" ("workflow_id", "status");

-- 11. run_activities
CREATE TABLE "public"."run_activities" (
  "id"            text PRIMARY KEY,
  "run_id"        text NOT NULL REFERENCES "public"."runs"("id") ON DELETE CASCADE,
  "parent_id"     text REFERENCES "public"."run_activities"("id") ON DELETE SET NULL,
  "type"          "public"."activity_type" NOT NULL,
  "status"        "public"."activity_status" NOT NULL DEFAULT 'pending',
  "step_label"    text,
  "title"         text,
  "description"   text,
  "detail"        jsonb,
  "started_at"    timestamptz,
  "completed_at"  timestamptz,
  "created_at"    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "run_activities_run_created_idx" ON "public"."run_activities" ("run_id", "created_at" ASC);

-- 12. approval_requests
CREATE TABLE "public"."approval_requests" (
  "id"              text PRIMARY KEY,
  "run_id"          text NOT NULL REFERENCES "public"."runs"("id") ON DELETE CASCADE,
  "workflow_id"     text REFERENCES "public"."workflows"("id") ON DELETE SET NULL,
  "thread_id"       text REFERENCES "public"."threads"("id") ON DELETE SET NULL,
  "user_id"         uuid NOT NULL,
  "tool_name"       text NOT NULL,
  "input"           jsonb,
  "schema"          jsonb,
  "status"          "public"."approval_status" NOT NULL DEFAULT 'pending',
  "auto_approved"   boolean NOT NULL DEFAULT false,
  "resolved_at"     timestamptz,
  "created_at"      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "approval_requests_status_created_idx" ON "public"."approval_requests" ("status", "created_at");
CREATE INDEX "approval_requests_thread_idx" ON "public"."approval_requests" ("thread_id");

-- 13. invites
CREATE TABLE "public"."invites" (
  "id"                text PRIMARY KEY,
  "kind"              "public"."invite_kind" NOT NULL,
  "workspace_id"      text NOT NULL REFERENCES "public"."workspaces"("id") ON DELETE CASCADE,
  "thread_id"         text REFERENCES "public"."threads"("id") ON DELETE SET NULL,
  "invited_by"        uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  "invitee_email"     text NOT NULL,
  "invited_user_id"   uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  "token_hash"        text NOT NULL UNIQUE,
  "role"              "public"."thread_role" NOT NULL DEFAULT 'editor',
  "status"            "public"."invite_status" NOT NULL DEFAULT 'pending',
  "expires_at"        timestamptz NOT NULL,
  "accepted_at"       timestamptz,
  "created_at"        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "invites_thread_idx" ON "public"."invites" ("thread_id");
CREATE INDEX "invites_token_hash_idx" ON "public"."invites" ("token_hash");

-- 14. thread_shares
CREATE TABLE "public"."thread_shares" (
  "id"            text PRIMARY KEY,
  "thread_id"     text NOT NULL REFERENCES "public"."threads"("id") ON DELETE CASCADE,
  "user_id"       uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  "role"          "public"."thread_role" NOT NULL DEFAULT 'editor',
  "invited_by"    uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  "invite_id"     text REFERENCES "public"."invites"("id") ON DELETE SET NULL,
  "created_at"    timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "thread_shares_thread_user_idx" ON "public"."thread_shares" ("thread_id", "user_id");

-- 15. notifications
CREATE TABLE "public"."notifications" (
  "id"            text PRIMARY KEY,
  "user_id"       uuid NOT NULL,
  "workspace_id"  text NOT NULL REFERENCES "public"."workspaces"("id") ON DELETE CASCADE,
  "thread_id"     text REFERENCES "public"."threads"("id") ON DELETE SET NULL,
  "type"          "public"."notification_type" NOT NULL,
  "title"         text NOT NULL,
  "body"          text NOT NULL DEFAULT '',
  "read_at"       timestamptz,
  "created_at"    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "notifications_user_read_created_idx" ON "public"."notifications" ("user_id", "read_at", "created_at" DESC);

-- 16. workspace_api_keys
CREATE TABLE "public"."workspace_api_keys" (
  "id"              text PRIMARY KEY,
  "workspace_id"    text NOT NULL REFERENCES "public"."workspaces"("id") ON DELETE CASCADE,
  "created_by"      uuid NOT NULL,
  "provider"        "public"."api_provider" NOT NULL,
  "key_encrypted"   bytea NOT NULL,
  "model_name"      text,
  "created_at"      timestamptz NOT NULL DEFAULT now(),
  "updated_at"      timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "workspace_api_keys_workspace_provider_idx" ON "public"."workspace_api_keys" ("workspace_id", "provider");

-- 17. files
CREATE TABLE "public"."files" (
  "id"              text PRIMARY KEY,
  "user_id"         uuid NOT NULL,
  "thread_id"       text REFERENCES "public"."threads"("id") ON DELETE SET NULL,
  "workspace_id"    text NOT NULL REFERENCES "public"."workspaces"("id") ON DELETE CASCADE,
  "bucket"          text NOT NULL DEFAULT 'chat-attachments',
  "path"            text NOT NULL,
  "mime_type"       text,
  "size_bytes"      bigint,
  "compressed"      boolean NOT NULL DEFAULT false,
  "created_at"      timestamptz NOT NULL DEFAULT now()
);

-- ─────────────────────────────────────────────────────────────────────
-- RLS HELPER FUNCTIONS (security definer / invoker)
-- ─────────────────────────────────────────────────────────────────────

-- Check if current user is a member of a workspace (any role)
CREATE OR REPLACE FUNCTION "public"."has_workspace_membership"("ws" text)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM "public"."workspace_members" wm
    WHERE wm."workspace_id" = "ws" AND wm."user_id" = auth.uid()
  );
$$;

-- Get current user's role in a workspace (NULL if not member and not owner)
CREATE OR REPLACE FUNCTION "public"."current_workspace_role"("ws" text)
RETURNS "public"."role"
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT wm."role" FROM "public"."workspace_members" wm
  WHERE wm."workspace_id" = "ws" AND wm."user_id" = auth.uid()
  LIMIT 1;
$$;

-- Is the user an editor or owner of a workspace?
CREATE OR REPLACE FUNCTION "public"."is_workspace_editor"("ws" text)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT current_workspace_role("ws") IN ('owner', 'editor');
$$;

-- Can the user read a thread? (owner, workspace member, or sharee)
CREATE OR REPLACE FUNCTION "public"."can_read_thread"("tid" text)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM "public"."threads" t
    WHERE t."id" = "tid" AND (
      t."user_id" = auth.uid()
      OR has_workspace_membership(t."workspace_id")
      OR EXISTS (
        SELECT 1 FROM "public"."thread_shares" ts
        WHERE ts."thread_id" = "tid" AND ts."user_id" = auth.uid()
      )
    )
  );
$$;

-- Can the user edit a thread? (owner of thread OR workspace editor)
CREATE OR REPLACE FUNCTION "public"."can_edit_thread"("tid" text)
RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM "public"."threads" t
    WHERE t."id" = "tid" AND (
      t."user_id" = auth.uid()
      OR is_workspace_editor(t."workspace_id")
    )
  );
$$;

-- Get workspace_id from a workflow
CREATE OR REPLACE FUNCTION "public"."ws_of_workflow"("wfid" text)
RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT w."workspace_id" FROM "public"."workflows" w WHERE w."id" = "wfid";
$$;

-- Get workspace_id from a run (via thread)
CREATE OR REPLACE FUNCTION "public"."ws_of_run"("rid" text)
RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT t."workspace_id" FROM "public"."runs" r
  JOIN "public"."threads" t ON t."id" = r."thread_id"
  WHERE r."id" = "rid";
$$;

